import { beforeEach, describe, expect, it, vi } from 'vitest';
import { fakeBrowser } from 'wxt/testing/fake-browser';
import { findCodeMock, type RunHandlerMessage } from './handlerRunner';
import { LogRouter } from './logRouter';
import { LOCALHOST_MATCHES } from './sites';
import { sanitizeLogDraft } from '../core/logSanitize';
import { siteStatus } from '../core/siteStatus';
import { BODY_CAP_BYTES, emptyState, newProject, type Mock, type SocketMock, type WemockState } from '../core/types';
import { loadState, updateState } from '../shared/store';

const EXT = 'extid';
const draft = (extra: Record<string, unknown> = {}) => ({
  method: 'GET', url: 'http://a.test/x', status: 200, responseHeaders: { a: '1' }, responseBody: '{"a":1}',
  responseEncoding: 'text', truncated: false, durationMs: 3, badge: 'real', startedAt: 1, ...extra,
});

describe('#4 sanitizeLogDraft', () => {
  it('keeps the known fields and drops the rest', () => {
    const d = sanitizeLogDraft({ ...draft({ mockId: 'm', connectionId: 'c', error: 'e', requestBody: 'q' }), evil: 1, __proto__x: 2 });
    expect(d).toEqual(draft({ mockId: 'm', connectionId: 'c', error: 'e', requestBody: 'q' }));
  });
  it('a body over the cap is not kept, and marked truncated', () => {
    const d = sanitizeLogDraft(draft({ responseBody: 'x'.repeat(BODY_CAP_BYTES + 1) }));
    expect(d).toMatchObject({ responseBody: null, truncated: true });
    const req = sanitizeLogDraft(draft({ requestBody: 'y'.repeat(BODY_CAP_BYTES + 1) }));
    expect(req!.requestBody).toBeUndefined();
  });
  it('a base64 body that is not valid base64 is dropped', () => {
    expect(sanitizeLogDraft(draft({ responseBody: '%%%', responseEncoding: 'base64' }))).toMatchObject({ responseBody: null, responseEncoding: 'base64' });
    expect(sanitizeLogDraft(draft({ responseBody: 'AAEC', responseEncoding: 'base64' }))!.responseBody).toBe('AAEC');
  });
  it('wrong types are refused', () => {
    expect(sanitizeLogDraft(draft({ status: '200' }))).toBeNull();
    expect(sanitizeLogDraft(draft({ badge: 'HACK' }))).toBeNull();
    expect(sanitizeLogDraft(draft({ responseHeaders: { a: 1 } }))).toBeNull();
    expect(sanitizeLogDraft(null)).toBeNull();
    expect(sanitizeLogDraft(draft({ url: 5 }))).toBeNull();
  });
});

function fakePort(url: string) {
  const posted: unknown[] = [];
  let onMsg: ((m: unknown) => void) | null = null;
  const port = {
    name: 'wemock-panel',
    sender: { id: EXT, url },
    postMessage: (m: unknown) => posted.push(m),
    onMessage: { addListener: (fn: (m: unknown) => void) => (onMsg = fn) },
    onDisconnect: { addListener: () => {} },
  };
  return { port, posted, send: (m: unknown) => onMsg?.(m) };
}

describe('#2 the Log survives a worker restart', () => {
  beforeEach(() => fakeBrowser.reset());
  it('a new router (a restarted worker) still has the rows', async () => {
    fakeBrowser.runtime.id = EXT;
    const a = new LogRouter();
    a.handleMessage({ type: 'log', entry: draft({ url: 'http://a.test/one' }) }, { tab: { id: 7 } });
    a.handleMessage({ type: 'log', entry: draft({ url: 'http://a.test/two' }) }, { tab: { id: 7 } });
    await vi.waitFor(async () => {
      const b = new LogRouter();
      const { port, posted, send } = fakePort(`chrome-extension://${EXT}/panel.html`);
      b.handleConnect(port);
      send({ type: 'subscribe', tabId: 7 });
      await vi.waitFor(() => expect(posted.length).toBeGreaterThan(0));
      const snap = posted[0] as { type: string; entries: { url: string }[] };
      expect(snap.type).toBe('snapshot');
      expect(snap.entries.map((e) => e.url)).toEqual(['http://a.test/one', 'http://a.test/two']);
    });
  });
  it('a row that arrives first, then a subscribe at once, still gets the stored rows', async () => {
    fakeBrowser.runtime.id = EXT;
    await fakeBrowser.storage.session.set({ 'wemock.log.7': [{ ...draft({ url: 'http://a.test/old' }), id: 'old' }] });
    const b = new LogRouter();
    b.handleMessage({ type: 'log', entry: draft({ url: 'http://a.test/new' }) }, { tab: { id: 7 } });
    const { port, posted, send } = fakePort(`chrome-extension://${EXT}/panel.html`);
    b.handleConnect(port);
    send({ type: 'subscribe', tabId: 7 });
    await vi.waitFor(() => expect(posted.length).toBeGreaterThan(0));
    const snap = posted[0] as { entries: { url: string }[] };
    expect(snap.entries.map((e) => e.url)).toEqual(['http://a.test/old', 'http://a.test/new']);
  });
});

describe('#11 only our own pages may subscribe to a log', () => {
  beforeEach(() => fakeBrowser.reset());
  it('a port from a web page gets nothing', async () => {
    fakeBrowser.runtime.id = EXT;
    const r = new LogRouter();
    r.handleMessage({ type: 'log', entry: draft() }, { tab: { id: 7 } });
    const evil = fakePort('https://evil.test/page');
    r.handleConnect(evil.port);
    evil.send({ type: 'subscribe', tabId: 7 });
    const good = fakePort(`chrome-extension://${EXT}/panel.html?tabId=7`);
    r.handleConnect(good.port);
    good.send({ type: 'subscribe', tabId: 7 });
    await vi.waitFor(() => expect(good.posted.length).toBeGreaterThan(0));
    expect(evil.posted).toEqual([]);
  });
});

describe('#10 a page runs only active, enabled code mocks', () => {
  const code = (id: string, enabled = true): Mock => ({
    id, enabled, method: 'GET', urlPattern: '/x', reply: 'code', code: 'return 1', source: 'manual', createdAt: 0,
    response: { status: 200, headers: {}, body: '', bodyEncoding: 'text', delayMs: 0 },
  });
  function state(active: string): WemockState {
    const p = newProject('pa', 'http://a.test');
    p.scenarios[0]!.mocks.push(code('def'), code('def-off', false));
    p.scenarios.push({ id: 's2', name: 'Two', mocks: [code('two')] }, { id: 's3', name: 'Three', mocks: [code('three')] });
    p.activeScenarioId = active;
    return { ...emptyState(), projects: [p] };
  }
  const tab = { id: EXT, url: 'http://a.test/page', tab: { id: 1 } };
  const msg = (mockId: string): RunHandlerMessage => ({ type: 'run-handler', mockId, request: { method: 'GET', url: 'http://a.test/x', headers: {} } });
  it('the active scenario and Default, enabled only', () => {
    expect(findCodeMock(state('s2'), tab, msg('two'), EXT)?.id).toBe('two');
    expect(findCodeMock(state('s2'), tab, msg('def'), EXT)?.id).toBe('def');
    expect(findCodeMock(state('s2'), tab, msg('three'), EXT)).toBeNull();
    expect(findCodeMock(state('s2'), tab, msg('def-off'), EXT)).toBeNull();
  });
  it('socket code rules: only of enabled sockets in the active scenario or Default', () => {
    const sock = (id: string, ruleId: string, enabled = true): SocketMock => ({
      id, enabled, kind: 'plain', urlPattern: '/ws', onConnect: [], createdAt: 0,
      replies: [{ id: ruleId, when: '', respond: 'code', result: '', code: 'return 1', pushes: [] }],
    });
    const s = state('s2');
    const p = s.projects[0]!;
    p.scenarios[0]!.sockets = [sock('w-def', 'r-def'), sock('w-off', 'r-off', false)];
    p.scenarios[1]!.sockets = [sock('w-two', 'r-two')];
    p.scenarios[2]!.sockets = [sock('w-three', 'r-three')];
    expect(findCodeMock(s, tab, msg('r-def'), EXT)?.id).toBe('r-def');
    expect(findCodeMock(s, tab, msg('r-two'), EXT)?.id).toBe('r-two');
    expect(findCodeMock(s, tab, msg('r-off'), EXT)).toBeNull();
    expect(findCodeMock(s, tab, msg('r-three'), EXT)).toBeNull();
  });
  it('the panel can still run any of its project\'s code mocks (the Test bar)', () => {
    const panel = { id: EXT, url: `chrome-extension://${EXT}/panel.html` };
    expect(findCodeMock(state('s2'), panel, { ...msg('three'), projectId: 'pa' }, EXT)?.id).toBe('three');
  });
});

describe('#3 https localhost is always on', () => {
  it('siteStatus and the registered matches agree', () => {
    expect(siteStatus('https://localhost:7001/', [], true)).toBe('on');
    expect(siteStatus('https://127.0.0.1:5001/', [], true)).toBe('on');
    expect(LOCALHOST_MATCHES).toEqual(expect.arrayContaining(['http://localhost/*', 'http://127.0.0.1/*', 'https://localhost/*', 'https://127.0.0.1/*']));
  });
});

describe('#8 state writes never lose an update', () => {
  beforeEach(() => fakeBrowser.reset());
  it('updates started together all land', async () => {
    await Promise.all(Array.from({ length: 10 }, (_, i) =>
      updateState((s) => ({ ...s, enabledOrigins: [...s.enabledOrigins, `http://site${i}.test`] }))));
    expect((await loadState()).enabledOrigins).toHaveLength(10);
  });
});
